INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(210000, 210, 0, 1, 0, 0, 0, 0, 'Icecrown', 'Dark and inescapably cold, its glaciers so hardened and desecrated that the ice has turned black. When Kil''jaeden hurled Ner''zhul''s prison down onto the glacier, it made the Frozen Throne, and the impact was seen as far away as the Grizzly Hills. From here the first Lich King made the Scourge, and nearly all blight and undeath on Azeroth flows from here still.\n\nArthas came and freed him, and they became one. Since then, the Scourge has fortified the whole region: walls, gates and great walkways of saronite connect its fortresses, and Icecrown Citadel looms over it all.', 'warcraft.wiki.gg: Icecrown (introduction, History, Wrath of the Lich King)'),
(210001, 210, 1, 1, 0, 0, 0, 0, 'The Three Gates', 'Icecrown is divided by high walls, each pierced by one gate, all made almost entirely of near-indestructible saronite and manned by huge Scourge constructs: Mord''rethar, the Death Gate; Aldur''thar, the Desolation Gate; and Corp''rethar, the Horror Gate, the last before the citadel. Any army bound for the Lich King must break them in turn. In the Valley of Fallen Heroes beyond the second, fallen champions of the Horde and Alliance rise again as champions of the Scourge.', 'warcraft.wiki.gg: Icecrown (Geography); warcraft.wiki.gg: Corp''rethar: The Horror Gate; warcraft.wiki.gg: Valley of Fallen Heroes'),
(210002, 210, 1, 2, 0, 0, 0, 0, 'The Argent Vanguard', 'The Argent Crusade''s first foothold in Icecrown, in the Valley of Echoes, under Highlord Tirion Fordring. From it the Crusade pushes into Scourgeholme, a fortress of slaughterhouses and ziggurats, and holds Crusaders'' Pinnacle, taken back from the Scourge.', 'warcraft.wiki.gg: Argent Vanguard; warcraft.wiki.gg: Scourgeholme; warcraft.wiki.gg: Crusaders'' Pinnacle'),
(210003, 210, 1, 3, 0, 0, 0, 0, 'The Skybreaker', 'A marvel of gnomish and dwarven engineering: an Alliance gunship with over twenty broadside cannons, a crew of marines and a massive bomb in its lowest deck, flying over the Lich King''s walls to cover the Alliance forces on the glacier below. High Captain Justin Bartlett commands it. Since the Horde''s Orgrim''s Hammer arrived, the two ships have squared off as often as they have fought the Scourge.', 'warcraft.wiki.gg: Skybreaker (Background)'),
(210004, 210, 1, 4, 0, 0, 0, 0, 'Orgrim''s Hammer', 'The Horde''s gunship over Icecrown, which serves in place of a ground base, for there is nowhere safe to build one. It and the Skybreaker are each in constant danger from the other, and from the Scourge.', 'warcraft.wiki.gg: Orgrim''s Hammer'),
(210005, 210, 1, 5, 0, 0, 0, 0, 'The Shadow Vault', 'Like a piece of Icecrown Citadel that wandered off to brood over the North Sea, its bladed crown jutting from the mountains. The Knights of the Ebon Blade took it from the Scourge for their base against the vrykul of Jotunheim, and the Scourge attacks it constantly.', 'warcraft.wiki.gg: Shadow Vault; warcraft.wiki.gg: Death''s Rise'),
(210006, 210, 1, 6, 0, 0, 0, 0, 'Jotunheim', 'The largest vrykul village in Northrend, a string of halls winding along the cliffs above the North Sea, where the vrykul first woke from their sleep. At Valhalas the vrykul fight for the right to become Ymirjar. Balargarde Fortress, at its end, tries to put Utgarde Keep to shame in size and number of skulls.', 'warcraft.wiki.gg: Jotunheim; warcraft.wiki.gg: Valhalas; warcraft.wiki.gg: Balargarde Fortress'),
(210007, 210, 1, 7, 0, 0, 0, 0, 'Ymirheim', 'A ramshackle wooden village wrapped around a high mountain valley over the saronite mines, the most important place of all to the vrykul. It is home to the Ymirjar, the elite warrior caste King Ymiron created to serve the Lich King. Their slaves work the mines, and slowly lose their minds, for the saronite is the blood of an Old God.', 'warcraft.wiki.gg: Ymirheim; warcraft.wiki.gg: Saronite Mines'),
(210008, 210, 1, 8, 0, 0, 0, 0, 'Sindragosa''s Fall', 'In the War of the Ancients many blue dragons fell here, on ground the glacier later buried. Among them was Malygos'' consort Sindragosa, who died trying to reach the Dragonblight. Thousands of years later, the Lich King came to her bones and raised her as a mighty frost wyrm to lead the Frostbrood, and tore the spirits of her lost whelps into undeath before her eyes.', 'warcraft.wiki.gg: Sindragosa''s Fall'),
(210009, 210, 1, 9, 0, 0, 0, 0, 'Malykriss: The Vile Hold', 'An unfinished necropolis built all of saronite, the cutting edge of Scourge craft, meant to replace Acherus. Finished, it would have been indestructible. It is the seat of the Lich King''s metalworking, and in the quarry below, his new death knights are trained.', 'warcraft.wiki.gg: Malykriss: The Vile Hold'),
(210010, 210, 1, 10, 0, 0, 0, 0, 'The Fleshwerks', 'A vast Scourge facility above the avalanche into Sholazar, given over to making abominations and flesh giants. Disgusting even by the Scourge''s standards, it bubbles with poison and plague, and undead birds circle overhead.', 'warcraft.wiki.gg: Fleshwerks'),
(210011, 210, 1, 11, 0, 0, 0, 0, 'Onslaught Harbor', 'Islands off the western coast that the Scarlet Onslaught has taken for its harbour, crowned by its Crimson Cathedral.', 'warcraft.wiki.gg: Onslaught Harbor'),
(210012, 210, 1, 12, 0, 0, 0, 0, 'The Argent Tournament', 'Tirion Fordring has called the champions of every people to a great tournament in the shadow of Icecrown, to find those worthy to stand at the front in the final assault on the Lich King.', 'warcraft.wiki.gg: Argent Tournament; warcraft.wiki.gg: Argent Tournament Grounds'),
(210013, 210, 1, 13, 0, 0, 0, 0, 'The First Legion Forward Camp', 'A camp of Arthas'' 1st Legion, from before his fall; perhaps the first place he openly fought and killed his own men. Its footsoldiers and their captain are still here.', 'warcraft.wiki.gg: First Legion Forward Camp'),
(210014, 210, 1, 14, 0, 0, 0, 0, 'Silent Vigil', 'A graveyard in the north-eastern corner of Icecrown, near where a dying crusader, Bridenbrad, has made his camp, consumed by the plague.', 'warcraft.wiki.gg: Silent Vigil'),
(210015, 210, 1, 15, 0, 0, 0, 0, 'Icecrown Citadel', 'The Scourge''s greatest fortress and the Lich King''s last bastion: a fortress as big as a city, a cathedral of blades and claws of saronite rising out of a split in the Icecrown Glacier, built around the Frozen Throne.', 'warcraft.wiki.gg: Icecrown Citadel; warcraft.wiki.gg: Icecrown Glacier'),
(210050, 210, 3, 1, 0, 0, 0, 0, 'The Scarlet Assault', 'After the Third War, the Scarlet Crusade struck north and came within sight of the Lich King''s stronghold before the Scourge threw them back. Many of its high officers died here, among them Grand Admiral Barean Westwind.', 'warcraft.wiki.gg: Icecrown (History)');
